package local.pocketchat;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Paths;
import org.json.*;

/** Production report model over captured browser values; all fault variants are host-only. */
public final class FingerprintContextReportHost {
  static int checks;static final JSONArray assertions=new JSONArray();
  static void check(String name,boolean pass){assertions.put(J.obj("name",name,"pass",pass));if(!pass)throw new AssertionError(name);checks++;}
  static JSONObject copy(JSONObject value){try{return new JSONObject(value.toString());}catch(JSONException error){throw new IllegalArgumentException(error);}}
  static JSONObject row(JSONArray rows,String key){for(int i=0;i<rows.length();i++){JSONObject value=rows.optJSONObject(i);if(value!=null&&key.equals(value.optString("key")))return value;}throw new AssertionError("Missing row "+key);}
  static JSONObject coverage(JSONObject sample,JSONArray rows,boolean observed,boolean fresh){return AuditReport.apiContextCoverage(rows,sample,observed,fresh);}
  static JSONObject coverage(JSONObject sample){return coverage(sample,new JSONArray(),true,true);}
  static JSONObject context(JSONObject sample,String name){return sample.optJSONObject("apiContexts").optJSONObject(name);}
  static JSONObject probe(JSONObject sample,String name,String api){return context(sample,name).optJSONObject("probes").optJSONObject(api);}
  static String state(JSONObject coverage,String context,String api){return coverage.optJSONObject(context).optJSONObject("probes").optJSONObject(api).optString("state");}
  static boolean allUncovered(JSONObject value,String name){for(String api:new String[]{"canvas","audio","fonts","webgl"})if(!AuditReport.UNCOVERED.equals(state(value,name,api)))return false;return true;}
  static boolean noVerdict(JSONObject value){return Boolean.FALSE.equals(value.opt("protectionVerified"));}
  public static void main(String[] args)throws Exception{
    JSONObject fixture=new JSONObject(new String(Files.readAllBytes(Paths.get(args[0])),StandardCharsets.UTF_8));JSONObject original=fixture.getJSONObject("sample"),capture=fixture.getJSONObject("capture");String input=original.toString();
    check("Fixture records actual Chromium capture and explicitly no Android or Gecko execution",Boolean.TRUE.equals(capture.opt("actualChromiumExecution"))&&Boolean.FALSE.equals(capture.opt("actualGeckoExecution"))&&Boolean.FALSE.equals(capture.opt("actualAndroidExecution")));
    check("Actual captured nonce and page provenance remain unchanged",original.optString("nonce").equals("context-browser-case")&&"page-main-world".equals(original.optString("provenance")));
    JSONObject page=context(original,"frame"),worker=context(original,"worker");
    check("Actual captured frame source and original page budgets are retained","same-origin-srcdoc".equals(page.optString("source"))&&page.getJSONObject("limits").getInt("audioFrames")==2048&&page.getJSONObject("limits").getInt("fontCandidates")==5);
    check("Actual captured Worker source and zero audio font operation budgets are retained","dedicated-worker".equals(worker.optString("source"))&&worker.getJSONObject("limits").getInt("audioFrames")==0&&worker.getJSONObject("limits").getInt("fontCandidates")==0);
    JSONArray rows=new JSONArray();JSONObject positive=coverage(original,rows,true,true);
    check("Actual frame canvas observation remains available",AuditReport.AVAILABLE.equals(state(positive,"frame","canvas")));
    check("Actual frame audio font and WebGL observations remain available",AuditReport.AVAILABLE.equals(state(positive,"frame","audio"))&&AuditReport.AVAILABLE.equals(state(positive,"frame","fonts"))&&AuditReport.AVAILABLE.equals(state(positive,"frame","webgl")));
    check("Actual Worker canvas with zero audio font limits remains available",AuditReport.AVAILABLE.equals(state(positive,"worker","canvas")));
    check("Actual Worker WebGL readback remains available",AuditReport.AVAILABLE.equals(state(positive,"worker","webgl"))&&probe(original,"worker","webgl").getInt("readbackPixels")==256&&probe(original,"worker","webgl").getInt("readbackBytes")==1024);
    check("Actual Worker audio and font omissions remain uncovered",AuditReport.UNCOVERED.equals(state(positive,"worker","audio"))&&AuditReport.UNCOVERED.equals(state(positive,"worker","fonts")));
    check("Each context has separate source and probe version and no protection verdict","same-origin-srcdoc".equals(positive.getJSONObject("frame").optString("source"))&&"dedicated-worker".equals(positive.getJSONObject("worker").optString("source"))&&positive.getJSONObject("frame").optInt("probeVersion")==1&&positive.getJSONObject("worker").optInt("probeVersion")==1&&noVerdict(positive)&&noVerdict(positive.getJSONObject("frame"))&&noVerdict(positive.getJSONObject("worker")));
    boolean operationsOnly=rows.length()==8;for(int i=0;i<rows.length();i++)operationsOnly&=!AuditReport.ISSUE.equals(rows.getJSONObject(i).optString("state"))&&!AuditReport.VERIFIED.equals(rows.getJSONObject(i).optString("state"));check("API rows report operations and never fingerprint or cross context issue verdicts",operationsOnly);
    check("Worker not applicable detail stays explicit",row(rows,"api-worker-audio").optString("detail").contains("不适用")&&row(rows,"api-worker-fonts").optString("detail").contains("未覆盖"));
    check("Frame WebGL label does not claim a readback that was not sampled",!row(rows,"api-frame-webgl").optString("name").contains("读回")&&row(rows,"api-worker-webgl").optString("name").contains("读回")&&!probe(original,"frame","webgl").has("readbackPixels"));
    JSONObject full=copy(original);full.put("mainWorld",J.obj("observed",true));JSONObject parent=full.getJSONObject("parent"),expected=J.obj("engine","gecko","ua",parent.optString("ua"),"major",AuditReport.major(parent.optString("ua")),"language",parent.optString("language"),"offset",parent.optInt("offset"),"level",1);
    JSONObject report=AuditReport.build(full,new JSONObject(),expected,false,true);check("Full report uses the same actual context values through an explicitly host constructed bridge envelope",AuditReport.AVAILABLE.equals(state(report.getJSONObject("apiContextOperationCoverage"),"worker","canvas"))&&AuditReport.AVAILABLE.equals(state(report.getJSONObject("apiContextOperationCoverage"),"frame","fonts")));
    check("Full report explicitly denies full fingerprint and API protection acceptance",Boolean.FALSE.equals(report.opt("apiProtectionVerified"))&&Boolean.FALSE.equals(report.opt("fingerprintTemplateAcceptance"))&&Boolean.FALSE.equals(report.opt("fullDesktopUaConsistency")));
    JSONObject light=copy(original);light.remove("apiContexts");JSONArray noRows=new JSONArray();JSONObject noCoverage=coverage(light,noRows,true,true);check("Ordinary observation without context API payload creates no context operations",Boolean.FALSE.equals(noCoverage.opt("requested"))&&noRows.length()==0&&noVerdict(noCoverage));
    for(Object requested:new Object[]{false,"true",JSONObject.NULL}){JSONObject bad=copy(original);bad.getJSONObject("apiContexts").put("requested",requested);JSONArray empty=new JSONArray();JSONObject value=coverage(bad,empty,true,true);check("Non true explicit API request cannot enable context coverage "+String.valueOf(requested),Boolean.FALSE.equals(value.opt("requested"))&&empty.length()==0);}
    for(Object schema:new Object[]{2,"1",JSONObject.NULL}){JSONObject bad=copy(original);bad.getJSONObject("apiContexts").put("schema",schema);JSONObject value=coverage(bad);check("Malformed context envelope schema invalidates both contexts "+String.valueOf(schema),allUncovered(value,"frame")&&allUncovered(value,"worker"));}
    for(boolean observed:new boolean[]{false,true})for(boolean fresh:new boolean[]{false,true})if(!observed||!fresh){JSONObject value=coverage(original,new JSONArray(),observed,fresh);check("Missing main world or stale document cannot verify context APIs "+observed+" "+fresh,allUncovered(value,"frame")&&allUncovered(value,"worker")&&noVerdict(value));}
    JSONObject fallback=copy(full);fallback.put("provenance","extension-isolated-world-fallback").put("mainWorld",J.obj("observed",false));JSONObject fallbackReport=AuditReport.build(fallback,new JSONObject(),expected,false,true);check("Full isolated world fallback cannot supply frame or Worker API coverage",allUncovered(fallbackReport.getJSONObject("apiContextOperationCoverage"),"frame")&&allUncovered(fallbackReport.getJSONObject("apiContextOperationCoverage"),"worker"));
    for(String name:new String[]{"frame","worker"}){
      String other="frame".equals(name)?"worker":"frame";
      for(String field:new String[]{"source","schema","probeVersion","requested","protectionVerified"}){
        JSONObject bad=copy(original),target=context(bad,name);Object invalid="source".equals(field)?"page-main-world":"requested".equals(field)?"true":"protectionVerified".equals(field)?true:2;target.put(field,invalid);JSONObject value=coverage(bad);
        check("Invalid context envelope is local to its source "+name+" "+field,allUncovered(value,name)&&AuditReport.AVAILABLE.equals(state(value,other,"canvas")));
      }
      JSONObject missing=copy(original);context(missing,name).remove("limits");check("Missing context limits stay uncovered "+name,allUncovered(coverage(missing),name));
      for(String limit:new String[]{"canvasPixels","audioFrames","fontCandidates","totalBudgetMs"}){JSONObject bad=copy(original);context(bad,name).getJSONObject("limits").put(limit,"totalBudgetMs".equals(limit)?1201:"audioFrames".equals(limit)?("worker".equals(name)?2048:0):"fontCandidates".equals(limit)?("worker".equals(name)?5:0):"4096");check("Wrong context operation limit stays uncovered "+name+" "+limit,allUncovered(coverage(bad),name));}
      JSONObject pixels=copy(original);probe(pixels,name,"canvas").put("pixels","4096");check("String pixel count cannot claim available canvas "+name,AuditReport.UNCOVERED.equals(state(coverage(pixels),name,"canvas")));
      for(String illegal:new String[]{"verified","issue","invented"}){JSONObject bad=copy(original);probe(bad,name,"canvas").put("state",illegal);check("Invented operation state is uncovered "+name+" "+illegal,AuditReport.UNCOVERED.equals(state(coverage(bad),name,"canvas")));}
      for(String operationState:new String[]{"restricted","failed","uncovered"}){JSONObject bad=copy(original);probe(bad,name,"canvas").put("state",operationState).put("reason","host-labelled-boundary");check("Non successful API state is retained without leak interpretation "+name+" "+operationState,operationState.equals(state(coverage(bad),name,"canvas")));}
      JSONObject unavailable=copy(original);context(unavailable,name).put("source","unavailable").put("expectedSource",name.equals("worker")?"dedicated-worker":"same-origin-srcdoc");check("CSP or missing context cannot substitute main page values "+name,allUncovered(coverage(unavailable),name));
    }
    for(String field:new String[]{"readbackPixels","readbackBytes","readbackHash","readbackHashAlgorithm"}){JSONObject bad=copy(original);probe(bad,"worker","webgl").remove(field);check("Missing actual Worker WebGL readback field stays uncovered "+field,AuditReport.UNCOVERED.equals(state(coverage(bad),"worker","webgl")));}
    for(String field:new String[]{"readbackPixels","readbackBytes"}){JSONObject bad=copy(original);probe(bad,"worker","webgl").put(field,field.equals("readbackPixels")?"256":2048);check("Wrong Worker WebGL readback dimensions stay uncovered "+field,AuditReport.UNCOVERED.equals(state(coverage(bad),"worker","webgl")));}
    JSONObject hash=copy(original);probe(hash,"worker","webgl").put("readbackHash","not-a-sha256");check("Invalid Worker readback hash cannot verify readback",AuditReport.UNCOVERED.equals(state(coverage(hash),"worker","webgl")));
    JSONObject noHash=copy(original);probe(noHash,"worker","webgl").remove("readbackHash");probe(noHash,"worker","webgl").remove("readbackHashAlgorithm");probe(noHash,"worker","webgl").put("readbackHashUnavailable",true);check("Explicit missing digest can retain an actually completed bounded readback",AuditReport.AVAILABLE.equals(state(coverage(noHash),"worker","webgl")));
    probe(noHash,"worker","webgl").put("readbackHashUnavailable","true");check("String missing digest flag cannot claim Worker readback",AuditReport.UNCOVERED.equals(state(coverage(noHash),"worker","webgl")));
    for(String api:new String[]{"audio","fonts"}){JSONObject bad=copy(original);context(bad,"worker").getJSONObject("probes").put(api,copy(probe(original,"frame",api)));check("Worker payload cannot claim an unimplemented frame interface "+api,AuditReport.UNCOVERED.equals(state(coverage(bad),"worker",api)));}
    JSONObject different=copy(original);different.getJSONObject("apiChecks").getJSONObject("probes").getJSONObject("canvas").put("hash",repeat('a'));probe(different,"frame","canvas").put("hash",repeat('b'));probe(different,"worker","canvas").put("hash",repeat('c'));JSONArray differenceRows=new JSONArray();JSONObject differentCoverage=coverage(different,differenceRows,true,true);boolean unequalAccepted=AuditReport.AVAILABLE.equals(state(differentCoverage,"frame","canvas"))&&AuditReport.AVAILABLE.equals(state(differentCoverage,"worker","canvas"));for(int i=0;i<differenceRows.length();i++)unequalAccepted&=!AuditReport.ISSUE.equals(differenceRows.getJSONObject(i).optString("state"));check("Different valid context hashes do not become an issue or leak verdict",unequalAccepted&&noVerdict(differentCoverage));
    JSONObject texture=copy(original);probe(texture,"worker","webgl").put("maxTextureSize",1.5);check("Malformed real capability cannot claim Worker operation availability",AuditReport.UNCOVERED.equals(state(coverage(texture),"worker","webgl")));
    JSONObject extensions=copy(original);probe(extensions,"frame","webgl").put("extensions",new JSONArray("[\"OES_texture_float\",\"OES_texture_float\"]"));check("Repeated capability values do not become available frame WebGL",AuditReport.UNCOVERED.equals(state(coverage(extensions),"frame","webgl")));
    check("Original captured context values remain byte equivalent after labelled fault copies",input.equals(original.toString()));
    System.out.println(J.obj("schema",1,"status","passed","passed",checks,"total",checks,"checks",assertions,"actualAndroidExecution",false,"actualGeckoExecution",false,"actualChromiumExecution",false,"usesPreviouslyCapturedActualChromiumInput",true,"scope","Actual production AuditReport on JVM with preserved captured Chromium inputs and labelled host faults; no real-time browser/native-document freshness or protection effectiveness verdict").toString());
  }
  static String repeat(char value){char[] chars=new char[64];java.util.Arrays.fill(chars,value);return new String(chars);}
}
